package tw.com.tft.documentscanner;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.*;import java.util.concurrent.*;import tw.com.tft.documentscanner.imaging.*;import tw.com.tft.documentscanner.model.*;import tw.com.tft.documentscanner.session.ScanSessionStore;import tw.com.tft.documentscanner.util.*;import tw.com.tft.documentscanner.view.CropView;public class CropActivity extends AppCompatActivity{private final ExecutorService w=Executors.newSingleThreadExecutor();private ScanSessionStore store;private CropView cv;private ProgressBar pb;private TextView page,hint;private int loaded=-1;private Bitmap bm;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_crop);UiUtils.applyInsets(this,findViewById(R.id.rootCrop),false);store=ScanSessionStore.get(this);if(store.session().items.isEmpty()){finish();return;}cv=findViewById(R.id.cropView);pb=findViewById(R.id.progressCrop);page=findViewById(R.id.txtCropPage);hint=findViewById(R.id.txtDetectHint);findViewById(R.id.btnBackCrop).setOnClickListener(v->back());findViewById(R.id.btnHomeCrop).setOnClickListener(v->home());findViewById(R.id.btnNextCrop).setOnClickListener(v->next());}protected void onResume(){super.onResume();if(store!=null&&!store.session().items.isEmpty()&&loaded!=store.session().currentIndex)load();}private void load(){ScanSession s=store.session();int ix=s.currentIndex;ScanItem i=s.current();loaded=ix;page.setText((ix+1)+" / "+s.items.size());pb.setVisibility(View.VISIBLE);w.submit(()->{try{Bitmap b=ImageLoader.loadPreview(i.sourcePath,DeviceProfile.previewMaxSide(this));float[]p=i.corners;DocumentDetector.Result r=null;if(p==null){if("AI".equals(i.sourceType))p=new float[]{.01f,.01f,.99f,.01f,.99f,.99f,.01f,.99f};else if(ScannerApp.isOpenCvReady()){r=DocumentDetector.detect(b);p=r.corners;}else p=DocumentDetector.safeInset();i.corners=p;store.persist(this);}float[]fp=p;DocumentDetector.Result fr=r;runOnUiThread(()->{if(bm!=null&&!bm.isRecycled())bm.recycle();bm=b;cv.setBitmap(b);cv.setCornersNormalized(fp);pb.setVisibility(View.GONE);hint.setText(fr!=null&&fr.fallback?"抓邊信心較低，請手動確認。精細移動 0.36x。":"拖曳四角或邊線中點。精細移動 0.36x。 ");});}catch(Throwable e){runOnUiThread(()->{pb.setVisibility(View.GONE);Toast.makeText(this,"圖片載入失敗",Toast.LENGTH_LONG).show();});}});}private void save(){ScanItem i=store.session().current();i.corners=cv.getCornersNormalized();i.cropConfirmed=true;store.persist(this);}private void next(){save();ScanSession s=store.session();if(s.currentIndex<s.items.size()-1){s.currentIndex++;store.persist(this);load();}else{s.currentIndex=0;store.persist(this);loaded=-1;startActivity(new Intent(this,PreviewActivity.class));}}private void back(){save();if(store.session().currentIndex>0){store.session().currentIndex--;store.persist(this);load();}else home();}private void home(){new AlertDialog.Builder(this).setTitle("是否確定離開？").setMessage("回首頁會清除本次工作。 ").setNegativeButton("取消",null).setPositiveButton("回首頁",(d,x)->{store.clear(this);Intent i=new Intent(this,MainActivity.class);i.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK);startActivity(i);finishAffinity();}).show();}public void onBackPressed(){back();}protected void onDestroy(){super.onDestroy();w.shutdownNow();if(bm!=null&&!bm.isRecycled())bm.recycle();}}